const b = $input.first().json.body || $input.first().json;
return [{ json: {
  platform: b.platform || 'shopee',
  buyer: b.buyer_name || b.sender || 'Pembeli',
  pesan: b.message || b.text || '',
  order_id: b.order_id || '-'
}}];

const { pesan } = $input.first().json;
const t = pesan.toLowerCase();

const KB = [
  {k:['ready','stok','ada','tersedia'], a:'Ready kak, silakan langsung order ya. Stok terbatas.'},
  {k:['kirim','ekspedisi','berapa hari','sampai'], a:'Dikirim hari yang sama kalau order sebelum jam 3 sore. Estimasi 2-5 hari tergantung kota.'},
  {k:['warna','ukuran','size','varian'], a:'Semua varian ready kak. Bisa pilih langsung di halaman produk ya.'},
  {k:['nego','diskon','murah','boleh kurang'], a:'Harga sudah paling murah kak, margin kami tipis. Tapi ada gratis ongkir untuk min. Rp 100rb.'},
  {k:['ori','asli','fake','kw','bpom'], a:'100% original kak, garansi 7 hari. Bisa cek cod kalau tersedia di kota kak.'},
  {k:['cod','bayar di tempat'], a:'COD tersedia kak, tergantung kurir dan lokasi. Bisa dicek saat checkout.'},
  {k:['reseller','dropsi','grosir'], a:'Ada program reseller kak, bisa chat admin untuk harga khusus.'},
  {k:['halo','hai','hi','assalamualaikum'], a:'Halo kak! Ada yang bisa kami bantu? Silakan tanya seputar produk, stok, atau pengiriman.'}
];

let best = null, bestLen = 0;
for (const e of KB) {
  for (const k of e.k) {
    if (t.includes(k) && k.length > bestLen) { best = e; bestLen = k.length; }
  }
}

const jawab = best ? best.a :
  'Terima kasih sudah chat kak. Untuk pertanyaan ini, admin kami akan bales segera ya.';

return [{ json: { jawab, matched: !!best } }];
